-- Body area for every movement (Rob, 2026-11-22): the Movements page gets two filter rows,
-- Body area and Equipment. The old mixed category column stays for reference only.
alter table movements add column if not exists body_area text;
do $$
declare n int; total int;
begin
  update movements set body_area = 'cardio' where slug in ('1-mile-run', '1000m-row', '100m-sprint', '200m-run', '400m-run', '500m-row', '5k-run', '800m-run', 'air-bike', 'air-bike-calories', 'air-bike-intervals', 'battle-ropes', 'bike-erg', 'butt-kickers', 'curved-treadmill-run', 'double-unders', 'echo-bike', 'gasser', 'high-knees', 'jump-rope-intervals', 'jumping-jacks', 'ladder-climb', 'medicine-ball-run', 'plate-run', 'row-for-calories', 'rowing', 'running', 'shuttle-run', 'single-unders', 'ski-erg', 'sprint-25m', 'stair-climb', 'swimming', 'treadmill-incline-walk', 'triple-unders', 'vertical-climb');
  get diagnostics n = row_count; if n <> 36 then raise exception 'cardio: expected 36, got %', n; end if;
  update movements set body_area = 'core' where slug in ('ab-wheel-rollout', 'bicycle-crunches', 'dead-bug', 'dragon-flag', 'floor-wipers', 'flutter-kicks', 'forward-rolls', 'ghd-sit-ups', 'hanging-hip-touches', 'hanging-knee-raises', 'hanging-l-hold', 'hollow-holds', 'hollow-rocks', 'inverted-hang-lowers', 'kb-windmill', 'knees-to-elbows', 'l-sit', 'mountain-climbers', 'plank-hold', 'plank-shoulder-taps', 'prone-cobra', 'russian-twists', 'side-plank', 'sit-ups', 'superman-hold', 'toe-touches', 'toes-to-bar', 'v-ups', 'windshield-wipers');
  get diagnostics n = row_count; if n <> 29 then raise exception 'core: expected 29, got %', n; end if;
  update movements set body_area = 'full' where slug in ('ball-slams', 'bar-facing-burpees', 'bear-crawls', 'bear-hug-ball-carry', 'buddy-carry', 'burpee-bar-muscle-ups', 'burpee-box-jump-over', 'burpee-muscle-ups', 'burpee-pull-ups', 'burpees', 'clean-and-jerks', 'clean-pull', 'cleans', 'db-clean', 'db-clean-and-press', 'db-farmer-carry', 'db-man-makers', 'db-snatch', 'db-thrusters', 'dumbbell-burpee-deadlifts', 'dumbbell-hang-clean-and-jerk', 'dumbbell-hang-split-snatches', 'dumbbell-split-cleans', 'dumbbell-squat-cleans', 'dumbbell-squat-snatches', 'dumbbell-thruster', 'farmers-carry', 'front-rack-hold', 'hang-power-cleans', 'hang-power-snatch', 'hang-squat-clean', 'inchworms', 'kb-clean', 'kb-clean-press', 'kb-farmer-carry', 'kb-figure-8', 'kb-snatch', 'kb-thruster', 'kb-turkish-get-up', 'kettlebell-front-rack-carry', 'kettlebell-overhead-carry', 'lateral-burpee-over-dumbbell', 'medicine-ball-clean', 'medicine-ball-slam', 'over-the-shoulder-sandbag-cleans', 'overhead-slam', 'overhead-walk', 'partner-barbell-carry', 'power-cleans', 'power-snatches', 'push-jerks', 'rotational-ball-slams', 'sandbag-carry', 'slam-ball-clean', 'slam-ball-over-the-shoulder', 'snatch-balance', 'snatches', 'split-jerk', 'sprawls', 'squat-cleans', 'squat-snatches', 'squat-thrusts', 'thrusters', 'tuck-jump-burpees', 'up-downs', 'waiters-walk', 'wall-balls');
  get diagnostics n = row_count; if n <> 67 then raise exception 'full: expected 67, got %', n; end if;
  update movements set body_area = 'lower' where slug in ('air-squats', 'back-extensions', 'back-squat', 'banded-deadlift', 'banded-hip-thrusts', 'banded-squats', 'barbell-good-morning', 'barbell-hip-thrust', 'barbell-lunge', 'belt-squat', 'belt-squat-march', 'belt-squat-romanian-deadlift', 'box-jump-over', 'box-jump-step-down', 'box-jumps', 'box-step-overs', 'broad-jumps', 'bulgarian-split-squats', 'calf-raises', 'cossack-squats', 'curtsy-lunges', 'db-deadlift', 'db-goblet-squat', 'db-lunges', 'db-romanian-deadlift', 'db-step-ups', 'deadlifts', 'donkey-kicks', 'dumbbell-front-squat', 'dumbbell-goblet-squat', 'dumbbell-romanian-deadlift', 'fire-hydrants', 'four-way-hip', 'frog-pumps', 'front-squats', 'ghd-hip-and-back-extension', 'glute-bridges', 'glute-ham-raise', 'good-mornings', 'hack-squat', 'hack-squat-calf-raise', 'hip-abduction', 'hip-adduction', 'hip-thrusts', 'jump-squats', 'kb-deadlift', 'kb-goblet-squats', 'kb-single-leg-deadlift', 'kb-sumo-deadlift-high-pull', 'kettlebell-front-rack-walking-lunges', 'kettlebell-swings', 'landmine-squat', 'lateral-lunges', 'leg-extension', 'leg-press', 'leg-press-calf-raise', 'lying-leg-curl', 'machine-glute-kickback', 'machine-hip-thrust', 'nordic-hamstring-curls', 'overhead-squats', 'overhead-walking-lunges', 'pendulum-calf-raise', 'pendulum-reverse-lunge', 'pendulum-squat', 'pistol-squats', 'reverse-hack-squat', 'reverse-hypers', 'reverse-lunges', 'romanian-deadlift', 'romanian-deadlift-bodyweight', 'seated-calf-raise', 'seated-leg-curl', 'single-leg-glute-bridge', 'sissy-squats', 'skaters', 'slam-ball-squat', 'sled-drag', 'sled-push', 'smith-machine-hip-thrust', 'smith-machine-squat', 'standing-calf-raise', 'step-ups', 'stiff-legged-deadlifts', 'sumo-deadlift-high-pulls', 'sumo-squats', 'tuck-jumps', 'walking-lunges', 'wall-sit', 'zercher-squat');
  get diagnostics n = row_count; if n <> 90 then raise exception 'lower: expected 90, got %', n; end if;
  update movements set body_area = 'upper' where slug in ('archer-push-ups', 'arm-over-arm-sled-pull', 'assisted-dips', 'assisted-pull-ups', 'banded-chest-press', 'banded-face-pulls', 'banded-pull-aparts', 'banded-rows', 'bar-dips', 'bar-hang', 'bar-muscle-up', 'barbell-row', 'bench-press', 'cable-chest-fly', 'cable-row', 'cable-triceps-pushdown', 'chest-supported-t-bar-row', 'chest-to-bar-pull-ups', 'chin-ups', 'clapping-push-ups', 'close-grip-lat-pulldown', 'db-arnold-press', 'db-bent-over-row', 'db-bicep-curls', 'db-floor-press', 'db-front-raises', 'db-lateral-raises', 'db-push-press', 'db-renegade-row', 'db-shoulder-press', 'decline-push-ups', 'deficit-push-ups', 'diamond-push-ups', 'dumbbell-push-press', 'elevated-pike-push-ups', 'hand-release-push-ups', 'handstand-hold', 'handstand-push-ups', 'handstand-walk', 'hindu-push-ups', 'inverted-rows', 'jumping-pull-ups', 'kb-halo', 'kb-overhead-press', 'kb-push-press', 'kb-rows', 'kipping-pull-ups', 'l-pull-ups', 'landmine-press', 'landmine-row', 'legless-rope-climb', 'machine-chest-press', 'machine-high-row', 'machine-low-row', 'machine-preacher-curl', 'machine-rear-delt-fly', 'machine-shoulder-press', 'muscle-ups', 'negative-pull-ups', 'overhead-press', 'pec-deck-fly', 'pike-push-ups', 'pseudo-planche-push-ups', 'pull-ups', 'push-press', 'push-ups', 'ring-dips', 'ring-push-ups', 'rope-climbs', 'shoulder-to-overhead', 'single-arm-lat-pulldown', 'skin-the-cat', 'smith-machine-bench-press', 'staggered-push-ups', 'tricep-dips', 'underhand-lat-pulldown', 'wall-walk', 'weighted-pull-ups', 'wide-grip-lat-pulldown', 'wide-push-ups');
  get diagnostics n = row_count; if n <> 80 then raise exception 'upper: expected 80, got %', n; end if;
  select count(*) into total from movements where body_area is null;
  if total > 0 then raise exception '% movements have no body area', total; end if;
end $$;
alter table movements add constraint movements_body_area_check check (body_area in ('upper','lower','core','full','cardio'));
select body_area, count(*) from movements group by body_area order by body_area;
